Given an array arr[] containing 2*n + 2 positive numbers, out of which 2*n numbers exist in pairs whereas the other two number occur exactly once and are distinct. The task is to find the other two numbers. Note: Return the numbers in increasing order. Example:Input: arr[] = [1, 2, 3, 2, 1, 4]Output: 3 4 Explanation: 3 and 4 occur exactly once.Input: arr[] = [2, 1, 3, 2]Output: 1 3Explanation: 1 and 3 occur exactly once.Try It YourselfTable of Content[Naive Approach] Nested Loop Frequency Counting - O(n^2) Time and O(1) Space[Expected Approach] Using Bit Manipulation - O(n) time and O(1) space[Naive Approach] Nested Loop Frequency Counting - O(n^2) Time and O(1) SpaceThis approach iterates through the array and counts the frequency of each element using a nested loop. For each element, the inner loop counts how many times it appears in the array. If an element appears exactly once, it is returned as the result. 
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;


vector<int> singleNum(vector<int>& arr) {
    int n = arr.size();

    vector<int> ans;
    // Iterate over every element
    for (int i = 0; i < n; i++) {

        // Initialize count to 0
        int count = 0;

        for (int j = 0; j < n; j++) {

            // Count the frequency of the element
            if (arr[i] == arr[j]) {
                count++;
            }
        }

        // If the frequency of the element is one
        if (count == 1) {
            ans.push_back(arr[i]);
        }
    }

    sort(ans.begin(), ans.end());
    // If no element exists at most once
    return ans;
}

int main() {
    vector<int> arr = { 1, 2, 3, 2, 1, 4 };
    vector<int> ans = singleNum(arr);
    for(auto it:ans)
        cout<<it<<" ";
    return 0;
}


